import{_ as t,a0 as o,w as r,s as d,I as i,x as a,a1 as e,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 Golang 的交叉编译 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Golang 的交叉编译 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Golang 的交叉编译 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Golang 的交叉编译 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210114 Cross-compiling made easy with Golang","title":"使用 Golang 的交叉编译","tag":"202105","desc":""},"relativePath":"202105/20210114 Cross-compiling made easy with Golang.md","filePath":"[post].md"}'),h={name:"202105/20210114 Cross-compiling made easy with Golang.md"};function g(u,s,c,k,b,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=i("h1",{id:"使用-golang-的交叉编译",tabindex:"-1"},[a("使用 Golang 的交叉编译 "),i("a",{class:"header-anchor",href:"#使用-golang-的交叉编译","aria-label":"Permalink to “使用 Golang 的交叉编译”"},"​")],-1)),s[25]||(s[25]=i("blockquote",null,[i("p",null,"走出舒适区，我了解了 Go 的交叉编译功能。")],-1)),s[26]||(s[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/13/092632nrg2z17i8vea4cf8.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("在 Linux 上测试软件时，我使用各种架构的服务器，例如 Intel、AMD、Arm 等。当我 ",-1)),e(n,{href:"https://opensource.com/article/20/12/linux-server"},{default:l(()=>[...s[0]||(s[0]=[a("分配了一台满足我的测试需求的 Linux 机器",-1)])]),_:1}),s[2]||(s[2]=a("，我仍然需要执行许多步骤：",-1))]),s[27]||(s[27]=p('<ol><li>下载并安装必备软件</li><li>验证构建服务器上是否有新的测试软件包</li><li>获取并设置依赖软件包所需的 yum 仓库</li><li>下载并安装新的测试软件包（基于步骤 2）</li><li>获取并设置必需的 SSL 证书</li><li>设置测试环境，获取所需的 Git 仓库，更改配置，重新启动守护进程等</li><li>做其他需要做的事情</li></ol><h3 id="用脚本自动化" tabindex="-1">用脚本自动化 <a class="header-anchor" href="#用脚本自动化" aria-label="Permalink to “用脚本自动化”">​</a></h3><p>这些步骤非常常规，以至于有必要对其进行自动化并将脚本保存到中央位置（例如文件服务器），在需要时可以在此处下载脚本。为此，我编写了 100-120 行的 Bash shell 脚本，它为我完成了所有配置（包括错误检查）。这个脚本通过以下方式简化了我的工作流程：</p><ol><li>配置新的 Linux 系统（支持测试的架构）</li><li>登录系统并从中央位置下载自动化 shell 脚本</li><li>运行它来配置系统</li><li>开始测试</li></ol><h3 id="学习-go-语言" tabindex="-1">学习 Go 语言 <a class="header-anchor" href="#学习-go-语言" aria-label="Permalink to “学习 Go 语言”">​</a></h3>',5)),i("p",null,[s[4]||(s[4]=a("我想学习 ",-1)),e(n,{href:"https://golang.org/"},{default:l(()=>[...s[3]||(s[3]=[a("Go 语言",-1)])]),_:1}),s[5]||(s[5]=a(" 有一段时间了，将我心爱的 Shell 脚本转换为 Go 程序似乎是一个很好的项目，可以帮助我入门。它的语法看起来很简单，在尝试了一些测试程序后，我开始着手提高自己的知识并熟悉 Go 标准库。",-1))]),s[28]||(s[28]=p(`<p>我花了一个星期的时间在笔记本电脑上编写 Go 程序。我经常在我的 x86 服务器上测试程序，清除错误并使程序健壮起来，一切都很顺利。</p><p>直到完全转换到 Go 程序前，我继续依赖自己的 shell 脚本。然后，我将二进制文件推送到中央文件服务器上，以便每次配置新服务器时，我要做的就是获取二进制文件，将可执行标志打开，然后运行二进制文件。我对早期的结果很满意：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://file.example.com/&lt;myuser&gt;/bins/prepnode</span></span>
<span class="line"><span>$ chmod  +x ./prepnode</span></span>
<span class="line"><span>$ ./prepnode</span></span></code></pre></div><h3 id="然后-出现了一个问题" tabindex="-1">然后，出现了一个问题 <a class="header-anchor" href="#然后-出现了一个问题" aria-label="Permalink to “然后，出现了一个问题”">​</a></h3><p>第二周，我从资源池中分配了一台新的服务器，像往常一样，我下载了二进制文件，设置了可执行标志，然后运行二进制文件。但这次它出错了，是一个奇怪的错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prepnode</span></span>
<span class="line"><span>bash: ./prepnode: cannot execute binary file: Exec format error</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>起初，我以为可能没有成功设置可执行标志。但是，它已按预期设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l prepnode</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 2640529 Dec 16 05:43 prepnode</span></span></code></pre></div><p>发生了什么事？我没有对源代码进行任何更改，编译没有引发任何错误或警告，而且上次运行时效果很好，因此我仔细查看了错误消息 <code>format error</code>。</p><p>我检查了二进制文件的格式，一切看起来都没问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode</span></span>
<span class="line"><span>prepnode: ELF 64-bit LSB executable, x86-64, version 1 (SYSV), statically linked, not stripped</span></span></code></pre></div><p>我迅速运行了以下命令，识别所配置的测试服务器的架构以及二进制试图运行的平台。它是 Arm64 架构，但是我编译的二进制文件（在我的 x86 笔记本电脑上）生成的是 x86-64 格式的二进制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -m</span></span>
<span class="line"><span>aarch64</span></span></code></pre></div><h3 id="脚本编写人员的编译第一课" tabindex="-1">脚本编写人员的编译第一课 <a class="header-anchor" href="#脚本编写人员的编译第一课" aria-label="Permalink to “脚本编写人员的编译第一课”">​</a></h3><p>在那之前，我从未考虑过这种情况（尽管我知道这一点）。我主要研究脚本语言（通常是 Python）以及 Shell 脚本。在任何架构的大多数 Linux 服务器上都可以使用 Bash Shell 和 Python 解释器。总之，之前一切都很顺利。</p>`,15)),i("p",null,[s[7]||(s[7]=a("但是，现在我正在处理 Go 这种编译语言，它生成可执行的二进制文件。编译后的二进制文件由特定架构的 ",-1)),e(n,{href:"https://en.wikipedia.org/wiki/Opcode"},{default:l(()=>[...s[6]||(s[6]=[a("指令码",-1)])]),_:1}),s[8]||(s[8]=a(" 或汇编指令组成，这就是为什么我收到格式错误的原因。由于 Arm64 CPU（运行二进制文件的地方）无法解释二进制文件的 x86-64 指令，因此它抛出错误。以前，shell 和 Python 解释器为我处理了底层指令码或特定架构的指令。",-1))]),s[29]||(s[29]=p(`<h3 id="go-的交叉编译" tabindex="-1">Go 的交叉编译 <a class="header-anchor" href="#go-的交叉编译" aria-label="Permalink to “Go 的交叉编译”">​</a></h3><p>我检查了 Golang 的文档，发现要生成 Arm64 二进制文件，我要做的就是在运行 <code>go build</code> 命令编译 Go 程序之前设置两个环境变量。</p><p><code>GOOS</code> 指的是操作系统，例如 Linux、Windows、BSD 等，而 <code>GOARCH</code> 指的是要在哪种架构上构建程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env GOOS=linux GOARCH=arm64 go build -o prepnode_arm64</span></span></code></pre></div><p>构建程序后，我重新运行 <code>file</code> 命令，这一次它显示的是 ARM AArch64，而不是之前显示的 x86。因此，我在我的笔记本上能为不同的架构构建二进制文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode_arm64</span></span>
<span class="line"><span>prepnode_arm64: ELF 64-bit LSB executable, ARM aarch64, version 1 (SYSV), statically linked, not stripped</span></span></code></pre></div><p>我将二进制文件从笔记本电脑复制到 ARM 服务器上。现在运行二进制文件（将可执行标志打开）不会产生任何错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prepnode_arm64  -h</span></span>
<span class="line"><span>Usage of ./prepnode_arm64:</span></span>
<span class="line"><span>  -c    Clean existing installation</span></span>
<span class="line"><span>  -n    Do not start test run (default true)</span></span>
<span class="line"><span>  -s    Use stage environment, default is qa</span></span>
<span class="line"><span>  -v    Enable verbose output</span></span></code></pre></div><h3 id="其他架构呢" tabindex="-1">其他架构呢？ <a class="header-anchor" href="#其他架构呢" aria-label="Permalink to “其他架构呢？”">​</a></h3><p>x86 和 Arm 是我测试软件所支持的 5 种架构中的两种，我担心 Go 可能不会支持其它架构，但事实并非如此。你可以查看 Go 支持的架构：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list</span></span></code></pre></div><p>Go 支持多种平台和操作系统，包括：</p><ul><li>AIX</li><li>Android</li><li>Darwin</li><li>Dragonfly</li><li>FreeBSD</li><li>Illumos</li><li>JavaScript</li><li>Linux</li><li>NetBSD</li><li>OpenBSD</li><li>Plan 9</li><li>Solaris</li><li>Windows</li></ul><p>要查找其支持的特定 Linux 架构，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list | grep linux</span></span></code></pre></div><p>如下面的输出所示，Go 支持我使用的所有体系结构。尽管 x86_64 不在列表中，但 AMD64 兼容 x86-64，所以你可以生成 AMD64 二进制文件，它可以在 x86 架构上正常运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list | grep linux</span></span>
<span class="line"><span>linux/386</span></span>
<span class="line"><span>linux/amd64</span></span>
<span class="line"><span>linux/arm</span></span>
<span class="line"><span>linux/arm64</span></span>
<span class="line"><span>linux/mips</span></span>
<span class="line"><span>linux/mips64</span></span>
<span class="line"><span>linux/mips64le</span></span>
<span class="line"><span>linux/mipsle</span></span>
<span class="line"><span>linux/ppc64</span></span>
<span class="line"><span>linux/ppc64le</span></span>
<span class="line"><span>linux/riscv64</span></span>
<span class="line"><span>linux/s390x</span></span></code></pre></div><h3 id="处理所有架构" tabindex="-1">处理所有架构 <a class="header-anchor" href="#处理所有架构" aria-label="Permalink to “处理所有架构”">​</a></h3><p>为我测试的所有体系结构生成二进制文件，就像从我的 x86 笔记本电脑编写一个微小的 shell 脚本一样简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/bash</span></span>
<span class="line"><span>archs=(amd64 arm64 ppc64le ppc64 s390x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for arch in \${archs[@]}</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>        env GOOS=linux GOARCH=\${arch} go build -o prepnode_\${arch}</span></span>
<span class="line"><span>done</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode_*</span></span>
<span class="line"><span>prepnode_amd64:   ELF 64-bit LSB executable, x86-64, version 1 (SYSV), statically linked, Go BuildID=y03MzCXoZERH-0EwAAYI/p909FDnk7xEUo2LdHIyo/V2ABa7X_rLkPNHaFqUQ6/5p_q8MZiR2WYkA5CzJiF, not stripped</span></span>
<span class="line"><span>prepnode_arm64:   ELF 64-bit LSB executable, ARM aarch64, version 1 (SYSV), statically linked, Go BuildID=q-H-CCtLv__jVOcdcOpA/CywRwDz9LN2Wk_fWeJHt/K4-3P5tU2mzlWJa0noGN/SEev9TJFyvHdKZnPaZgb, not stripped</span></span>
<span class="line"><span>prepnode_ppc64:   ELF 64-bit MSB executable, 64-bit PowerPC or cisco 7500, version 1 (SYSV), statically linked, Go BuildID=DMWfc1QwOGIq2hxEzL_u/UE-9CIvkIMeNC_ocW4ry/r-7NcMATXatoXJQz3yUO/xzfiDIBuUxbuiyaw5Goq, not stripped</span></span>
<span class="line"><span>prepnode_ppc64le: ELF 64-bit LSB executable, 64-bit PowerPC or cisco 7500, version 1 (SYSV), statically linked, Go BuildID=C6qCjxwO9s63FJKDrv3f/xCJa4E6LPVpEZqmbF6B4/Mu6T_OR-dx-vLavn1Gyq/AWR1pK1cLz9YzLSFt5eU, not stripped</span></span>
<span class="line"><span>prepnode_s390x:   ELF 64-bit MSB executable, IBM S/390, version 1 (SYSV), statically linked, Go BuildID=faC_HDe1_iVq2XhpPD3d/7TIv0rulE4RZybgJVmPz/o_SZW_0iS0EkJJZHANxx/zuZgo79Je7zAs3v6Lxuz, not stripped</span></span></code></pre></div><p>现在，每当配置一台新机器时，我就运行以下 <code>wget</code> 命令下载特定体系结构的二进制文件，将可执行标志打开，然后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://file.domain.com/&lt;myuser&gt;/bins/prepnode_&lt;arch&gt;</span></span>
<span class="line"><span>$ chmod +x ./prepnode_&lt;arch&gt;</span></span>
<span class="line"><span>$ ./prepnode_&lt;arch&gt;</span></span></code></pre></div><h3 id="为什么" tabindex="-1">为什么？ <a class="header-anchor" href="#为什么" aria-label="Permalink to “为什么？”">​</a></h3><p>你可能想知道，为什么我没有坚持使用 shell 脚本或将程序移植到 Python 而不是编译语言上来避免这些麻烦。所以有舍有得，那样的话我不会了解 Go 的交叉编译功能，以及程序在 CPU 上执行时的底层工作原理。在计算机中，总要考虑取舍，但绝不要让它们阻碍你的学习。</p><hr>`,26)),i("p",null,[s[10]||(s[10]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/1/go-cross-compiling"},{default:l(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/21/1/go-cross-compiling",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/gkamathe"},{default:l(()=>[...s[11]||(s[11]=[a("Gaurav Kamathe",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:l(()=>[...s[13]||(s[13]=[a("MjSeven",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const C=t(h,[["render",g]]);export{y as __pageData,C as default};
